INSERT INTO simulator.question_versions(id,question_id,version,section,task_type,status,content) VALUES ('50000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',1,'WRITING','BUILD_A_SENTENCE','APPROVED','{"taskType": "BUILD_A_SENTENCE", "title": "A study group invitation", "instructions": "Arrange every phrase once to form a grammatical sentence.", "elements": [{"id": "a", "text": "We can meet"}, {"id": "b", "text": "after class"}, {"id": "c", "text": "in the library"}], "difficulty": "A2", "skills": ["WORD_ORDER"], "expectedResponseFormat": "elementIds", "rubricRef": "sentence-variants-v1", "version": 1, "original": true}'::jsonb);
INSERT INTO simulator.answer_keys(question_version_id,answers,explanation) VALUES ('50000000-0000-0000-0000-000000000001','{"variants":[["a","b","c"],["a","c","b"]]}','The subject and modal verb phrase comes first. Both time and place adjunct orders are grammatical.');
